create table if not exists meeting_recordings (id uuid primary key default gen_random_uuid(), meeting_id uuid references meetings(id) on delete cascade, file_id uuid, storage_url text, duration_seconds int default 0, status text default 'processing', created_at timestamptz default now(), updated_at timestamptz default now()); alter table meeting_recordings enable row level security; create index if not exists idx_meeting_recordings_meeting on meeting_recordings(meeting_id);
